# Workboard

Requires Node.js 22.22.1. No external dependencies or installation step is needed.

Start the application:

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
```

Open http://localhost:8080. The server binds to `0.0.0.0`; `PORT` defaults to
`8080`, and `DB_PATH` defaults to `data/workboard.sqlite`. The SQLite file stores
project names and IDs, project tasks, and task completion across restarts.
Open a project to create tasks, check or uncheck completion, and filter by All,
Open, or Completed. `GET /health` returns `{"status":"ok"}`.
The project list filters Active and Archived projects and shows each project's
completed/total task count. Archive and restore projects from their rows.
Archived projects retain their tasks and filters while task creation and
completion changes are disabled. Archive state also persists across restarts;
existing databases are upgraded automatically.

Run the integration checks:

```sh
npm test
```
import http from 'node:http';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const dbPath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(dbPath), { recursive: true });
const database = new DatabaseSync(dbPath);
database.exec('PRAGMA foreign_keys = ON');
database.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
)`);
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
database.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id)`);
const listProjects = database.prepare(`SELECT projects.id, projects.name,
  COUNT(tasks.id) AS total, COALESCE(SUM(tasks.completed), 0) AS completed
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
  WHERE projects.archived = ? GROUP BY projects.id ORDER BY projects.id`);
const findProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const setProjectArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

function taskFilter(value) {
  return ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
}

function projectFilter(value) {
  return value === 'Archived' ? 'Archived' : 'Active';
}

async function readForm(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) return null;
  }
  return new URLSearchParams(body);
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #f5f7fb; color: #17243b; font: 16px/1.5 system-ui, sans-serif; }
    main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce2ec; border-radius: 12px; }
    h1 { margin: 0 0 24px; overflow-wrap: anywhere; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    input[type="text"], select { width: 100%; padding: 12px; border: 1px solid #8b98ab; border-radius: 6px; font: inherit; }
    input[type="checkbox"] { width: 20px; height: 20px; flex-shrink: 0; }
    button { padding: 10px 16px; border: 0; border-radius: 6px; background: #2456b8; color: white; font: inherit; cursor: pointer; }
    button:hover { background: #19428f; }
    button:disabled { background: #788397; cursor: not-allowed; }
    :focus-visible { outline: 3px solid #c47b00; outline-offset: 3px; }
    .create button { margin-top: 12px; }
    .projects { margin-top: 32px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 18px 0; border-top: 1px solid #dce2ec; }
    .project-name { overflow-wrap: anywhere; min-width: 0; }
    .project-row form { flex-shrink: 0; }
    .project-actions { display: flex; gap: 8px; flex-wrap: wrap; }
    [role="alert"] { color: #a32020; margin-bottom: 16px; }
    .empty { color: #58677e; }
    .task-controls { margin-top: 24px; }
    .task-row { padding: 18px 0; border-top: 1px solid #dce2ec; }
    .task-row label { display: flex; align-items: center; gap: 12px; margin: 0; font-weight: 400; }
    .task-title { overflow-wrap: anywhere; min-width: 0; }
    @media (max-width: 600px) { main { margin: 20px 12px; padding: 24px; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function projectsPage(error = '', filter = 'Active') {
  const projects = listProjects.all(filter === 'Archived' ? 1 : 0);
  return page('Projects', `
    <h1>Workboard</h1>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create" method="post" action="/projects">
      <input type="hidden" name="filter" value="${filter}">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Create project</button>
    </form>
    <form class="task-controls" method="get" action="/">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['Active', 'Archived'].map((value) => `<option${value === filter ? ' selected' : ''}>${value}</option>`).join('')}
      </select>
      <noscript><button type="submit">Apply filter</button></noscript>
    </form>
    <section class="projects" aria-label="Projects">
      ${projects.length ? projects.map((project) => `
        <div class="project-row" data-testid="project-row">
          <div class="project-name"><span>${escapeHtml(project.name)}</span>
            <div data-testid="project-summary">${project.completed}/${project.total} completed</div>
          </div>
          <div class="project-actions">
            <form method="get" action="/projects/${project.id}">
              <button type="submit">Open project</button>
            </form>
            <form method="post" action="/projects/${project.id}/${filter === 'Archived' ? 'restore' : 'archive'}">
              <button type="submit">${filter === 'Archived' ? 'Restore' : 'Archive'} project</button>
            </form>
          </div>
        </div>`).join('') : '<p class="empty">No projects in this filter.</p>'}
    </section>`);
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  response.end(html);
}

function projectPage(project, filter = 'All', error = '') {
  const tasks = listTasks.all(project.id).filter((task) =>
    filter === 'All' || Boolean(task.completed) === (filter === 'Completed'));
  return page(project.name, `
    <h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form method="get" action="/"><button type="submit">Projects</button></form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create task-controls" method="post" action="/projects/${project.id}/tasks">
      <input type="hidden" name="filter" value="${filter}">
      <label for="task-title">Task title</label>
      <input id="task-title" name="title" type="text" autocomplete="off">
      <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
    </form>
    <form class="task-controls" method="get" action="/projects/${project.id}">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['All', 'Open', 'Completed'].map((value) => `<option${value === filter ? ' selected' : ''}>${value}</option>`).join('')}
      </select>
      <noscript><button type="submit">Apply filter</button></noscript>
    </form>
    <section class="task-controls" aria-label="Tasks">
      ${tasks.length ? tasks.map((task) => `
        <div class="task-row" data-testid="task-row">
          <form method="post" action="/projects/${project.id}/tasks/${task.id}">
            <input type="hidden" name="filter" value="${filter}">
            <label><input type="checkbox" name="completed" value="1" aria-label="${escapeHtml(`Complete ${task.title}`)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()"><span class="task-title">${escapeHtml(task.title)}</span></label>
            <noscript><button type="submit"${project.archived ? ' disabled' : ''}>Save completion</button></noscript>
          </form>
        </div>`).join('') : '<p class="empty">No tasks match this filter.</p>'}
    </section>`);
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (request.method === 'GET' && url.pathname === '/') {
      sendHtml(response, 200, projectsPage('', projectFilter(url.searchParams.get('filter'))));
      return;
    }
    if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      if (!form) {
        sendHtml(response, 413, page('Request too large', '<h1>Request too large</h1>'));
        return;
      }
      const name = (form.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 400, projectsPage('Project name is required', projectFilter(form.get('filter'))));
        return;
      }
      createProject.run(name);
      response.writeHead(303, { Location: '/' });
      response.end();
      return;
    }
    const archiveRoute = /^\/projects\/([1-9]\d*)\/(archive|restore)$/.exec(url.pathname);
    if (request.method === 'POST' && archiveRoute) {
      const result = setProjectArchived.run(archiveRoute[2] === 'archive' ? 1 : 0, archiveRoute[1]);
      if (result.changes) {
        response.writeHead(303, { Location: archiveRoute[2] === 'archive' ? '/' : '/?filter=Archived' });
        response.end();
        return;
      }
    }
    const projectRoute = /^\/projects\/([1-9]\d*)$/.exec(url.pathname);
    if (request.method === 'GET' && projectRoute) {
      const project = findProject.get(projectRoute[1]);
      if (project) {
        sendHtml(response, 200, projectPage(project, taskFilter(url.searchParams.get('filter'))));
        return;
      }
    }
    const taskRoute = /^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/.exec(url.pathname);
    if (request.method === 'POST' && taskRoute) {
      const project = findProject.get(taskRoute[1]);
      if (project) {
        const form = await readForm(request);
        if (!form) {
          sendHtml(response, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
        const filter = taskFilter(form.get('filter'));
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filter, 'Archived project tasks cannot be changed'));
          return;
        }
        if (taskRoute[2]) {
          const result = updateTask.run(form.get('completed') === '1' ? 1 : 0, taskRoute[2], project.id);
          if (!result.changes) {
            sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
        } else {
          const title = (form.get('title') || '').trim();
          if (!title) {
            sendHtml(response, 400, projectPage(project, filter, 'Task title is required'));
            return;
          }
          createTask.run(project.id, title);
        }
        response.writeHead(303, { Location: `/projects/${project.id}?filter=${filter}` });
        response.end();
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Not found</h1><a href="/">Projects</a>'));
  } catch (error) {
    console.error(error);
    sendHtml(response, 500, page('Server error', '<h1>Server error</h1>'));
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => {
    server.close(() => {
      database.close();
      process.exit(0);
    });
  });
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { once } from 'node:events';
import { DatabaseSync } from 'node:sqlite';

test('projects and tasks support validation, filtering, isolation, archiving, summaries, and restart persistence', async (t) => {
  await mkdir('data', { recursive: true });
  const directory = await mkdtemp(join(process.cwd(), 'data', 'test-'));
  // Exercise upgrading the original projects schema without resetting its IDs or names.
  const previousDatabase = new DatabaseSync(join(directory, 'projects.sqlite'));
  previousDatabase.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    INSERT INTO projects (name) VALUES ('Existing project')`);
  previousDatabase.close();
  let child;
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  t.after(async () => {
    await stop();
    await rm(directory, { recursive: true, force: true });
  });
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'projects.sqlite') },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    const port = await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('Server did not start')), 5000);
      child.once('error', (error) => { clearTimeout(timeout); reject(error); });
      child.once('exit', (code) => { clearTimeout(timeout); reject(new Error(`Server exited: ${code}`)); });
      child.stdout.on('data', (chunk) => {
        const match = /listening on port (\d+)/.exec(chunk.toString());
        if (match) { clearTimeout(timeout); resolve(match[1]); }
      });
    });
    return `http://127.0.0.1:${port}`;
  }
  let base = await start();
  const health = await fetch(`${base}/health`);
  assert.equal(health.status, 200);
  assert.deepEqual(await health.json(), { status: 'ok' });
  const initial = await (await fetch(base)).text();
  assert.match(initial, /<h1>Workboard<\/h1>/);
  assert.match(initial, /<label for="project-name">Project name<\/label>/);
  assert.match(initial, />Create project<\/button>/);
  assert.match(initial, /Existing project/);
  assert.match(initial, /action="\/projects\/1"/);
  assert.match(initial, /data-testid="project-summary">0\/0 completed/);
  assert.match(initial, /<label for="project-filter">Project filter<\/label>/);
  assert.match(initial, /<option selected>Active<\/option><option>Archived<\/option>/);
  // Remove only the seeded migration fixture so the creation assertions remain independent.
  const fixtureDatabase = new DatabaseSync(join(directory, 'projects.sqlite'));
  fixtureDatabase.exec('DELETE FROM projects WHERE id = 1');
  fixtureDatabase.close();

  async function create(name) {
    return fetch(`${base}/projects`, {
      method: 'POST', body: new URLSearchParams({ name }), redirect: 'manual',
    });
  }
  for (const name of ['', ' \t\n ']) {
    const response = await create(name);
    assert.equal(response.status, 400);
    const html = await response.text();
    assert.match(html, /role="alert">Project name is required/);
    assert.doesNotMatch(html, /data-testid="project-row"/);
  }
  assert.equal((await create('  First project  ')).status, 303);
  assert.equal((await create('Second <project> & "team"')).status, 303);
  const list = await (await fetch(base)).text();
  assert.equal((list.match(/data-testid="project-row"/g) || []).length, 2);
  assert.match(list, />First project<\/span>/);
  assert.ok(list.indexOf('First project') < list.indexOf('Second &lt;project&gt;'));
  assert.match(list, /Second &lt;project&gt; &amp; &quot;team&quot;/);
  const paths = [...list.matchAll(/action="(\/projects\/\d+)"/g)].map((match) => match[1]);
  assert.equal(paths.length, 2);
  assert.notEqual(paths[0], paths[1]);
  const detail = await (await fetch(`${base}${paths[0]}`)).text();
  assert.match(detail, /<h1>First project<\/h1>/);
  assert.match(detail, /action="\/".*>Projects<\/button>/);
  const invalid = await create('   ');
  const invalidHtml = await invalid.text();
  assert.equal((invalidHtml.match(/data-testid="project-row"/g) || []).length, 2);
  assert.equal(await (await fetch(base)).text(), list);
  assert.equal((await fetch(`${base}/projects/99999`)).status, 404);

  async function taskPage(path = paths[0], filter = 'All') {
    return (await fetch(`${base}${path}?filter=${filter}`)).text();
  }
  async function postTask(path, values) {
    return fetch(`${base}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
  }
  const taskCount = (html) => (html.match(/data-testid="task-row"/g) || []).length;
  assert.match(detail, /<label for="task-title">Task title<\/label>/);
  assert.match(detail, />Create task<\/button>/);
  assert.match(detail, /<label for="task-filter">Task filter<\/label>/);
  assert.match(detail, /<option selected>All<\/option><option>Open<\/option><option>Completed<\/option>/);
  for (const title of ['', ' \t\n ']) {
    const response = await postTask(`${paths[0]}/tasks`, { title });
    assert.equal(response.status, 400);
    const html = await response.text();
    assert.match(html, /role="alert">Task title is required/);
    assert.equal(taskCount(html), 0);
  }
  assert.equal((await postTask(`${paths[0]}/tasks`, { title: '  First task  ' })).status, 303);
  assert.equal((await postTask(`${paths[0]}/tasks`, { title: 'Second <task> & "review"' })).status, 303);
  const openTasks = await taskPage();
  assert.equal(taskCount(openTasks), 2);
  assert.match(openTasks, /aria-label="Complete First task"/);
  assert.match(openTasks, /aria-label="Complete Second &lt;task&gt; &amp; &quot;review&quot;"/);
  assert.ok(openTasks.indexOf('First task') < openTasks.indexOf('Second &lt;task&gt;'));
  assert.doesNotMatch(openTasks, / checked/);
  assert.equal(taskCount(await taskPage(paths[0], 'Open')), 2);
  assert.equal(taskCount(await taskPage(paths[0], 'Completed')), 0);
  assert.equal(taskCount(await taskPage(paths[1])), 0);
  const taskPaths = [...openTasks.matchAll(/action="(\/projects\/\d+\/tasks\/\d+)"/g)].map((match) => match[1]);
  assert.equal(taskPaths.length, 2);
  const completion = await postTask(taskPaths[0], { completed: '1', filter: 'Open' });
  assert.equal(completion.status, 303);
  assert.equal(completion.headers.get('location'), `${paths[0]}?filter=Open`);
  const completed = await taskPage(paths[0], 'Completed');
  assert.equal(taskCount(completed), 1);
  assert.match(completed, /aria-label="Complete First task" checked/);
  assert.doesNotMatch(completed, /Second &lt;task&gt;/);
  const remaining = await taskPage(paths[0], 'Open');
  assert.equal(taskCount(remaining), 1);
  assert.doesNotMatch(remaining, /First task/);
  const wrongProjectPath = taskPaths[0].replace(paths[0], paths[1]);
  assert.equal((await postTask(wrongProjectPath, {})).status, 404);
  assert.equal(await taskPage(paths[0], 'Completed'), completed);
  assert.equal((await postTask(`${paths[0]}/tasks`, { title: '   ' })).status, 400);
  assert.equal(taskCount(await taskPage()), 2);
  assert.equal((await postTask(`${paths[1]}/tasks`, { title: 'Other project task' })).status, 303);
  assert.equal(taskCount(await taskPage(paths[1])), 1);
  assert.doesNotMatch(await taskPage(), /Other project task/);
  const savedTasks = await taskPage();
  const savedList = await (await fetch(base)).text();
  assert.match(savedList, /data-testid="project-summary">1\/2 completed/);
  assert.match(savedList, /data-testid="project-summary">0\/1 completed/);

  await stop();
  base = await start();
  assert.equal(await (await fetch(base)).text(), savedList);
  assert.equal(await taskPage(), savedTasks);
  assert.equal(await taskPage(paths[0], 'Completed'), completed);
  assert.equal(taskCount(await taskPage(paths[1])), 1);
  assert.equal((await postTask(taskPaths[0], {})).status, 303);
  assert.equal(taskCount(await taskPage(paths[0], 'Completed')), 0);
  assert.equal(taskCount(await taskPage(paths[0], 'Open')), 2);
  await stop();
  base = await start();
  assert.equal(taskCount(await taskPage(paths[0], 'Completed')), 0);
  assert.equal(await taskPage(), openTasks);

  assert.equal((await postTask(taskPaths[0], { completed: '1' })).status, 303);
  const beforeArchive = await taskPage();
  assert.equal((await postTask(`${paths[0]}/archive`, {})).status, 303);
  const activeList = await (await fetch(base)).text();
  assert.doesNotMatch(activeList, /First project/);
  assert.match(activeList, /Second &lt;project&gt;/);
  const archivedList = await (await fetch(`${base}/?filter=Archived`)).text();
  assert.match(archivedList, /First project/);
  assert.doesNotMatch(archivedList, /Second &lt;project&gt;/);
  assert.match(archivedList, />Open project<\/button>/);
  assert.match(archivedList, />Restore project<\/button>/);
  assert.doesNotMatch(archivedList, />Archive project<\/button>/);
  assert.match(archivedList, /data-testid="project-summary">1\/2 completed/);
  const archivedPage = await taskPage();
  assert.match(archivedPage, /<p>Archived project<\/p>/);
  assert.match(archivedPage, /<button type="submit" disabled>Create task<\/button>/);
  assert.equal((archivedPage.match(/type="checkbox"[^>]* disabled/g) || []).length, 2);
  assert.equal(taskCount(await taskPage(paths[0], 'Completed')), 1);
  assert.equal(taskCount(await taskPage(paths[0], 'Open')), 1);
  assert.equal((await postTask(`${paths[0]}/tasks`, { title: 'Blocked task' })).status, 403);
  assert.equal((await postTask(taskPaths[0], {})).status, 403);
  assert.equal(await taskPage(), archivedPage);
  // Task filters must not affect the project summary.
  assert.equal(await (await fetch(`${base}/?filter=Archived`)).text(), archivedList);
  await stop();
  base = await start();
  assert.equal(await (await fetch(base)).text(), activeList);
  assert.equal(await (await fetch(`${base}/?filter=Archived`)).text(), archivedList);
  assert.equal(await taskPage(), archivedPage);
  assert.equal((await postTask(`${paths[0]}/restore`, {})).status, 303);
